-- Lab results whose MRN matches no EHR patient cannot be used for screening.
REGISTER DQ lab_row_resolves_to_patient TABLE lightning.metastore.rrcc.trialmatch.lab AS patient_id IS NOT NULL;

-- A lab value without a unit cannot be compared with a criterion threshold.
REGISTER DQ lab_has_unit_and_value TABLE lightning.metastore.rrcc.trialmatch.lab AS unit IS NOT NULL AND value IS NOT NULL AND value >= 0;

-- Molecular reports must link to an EHR patient through the MRN.
REGISTER DQ biomarker_resolves_to_patient TABLE lightning.metastore.rrcc.trialmatch.biomarker AS patient_id IS NOT NULL;

-- Trials often require the assay type and date of a biomarker result.
REGISTER DQ biomarker_has_assay_and_date TABLE lightning.metastore.rrcc.trialmatch.biomarker AS assay IS NOT NULL AND reported_date IS NOT NULL;

-- Prior-therapy criteria depend on RxNav resolving every medication order.
REGISTER DQ therapy_class_resolved TABLE lightning.metastore.rrcc.trialmatch.therapy AS therapy_class <> 'UNRESOLVED';

-- Only recruiting trials belong on the worklist.
REGISTER DQ trial_is_recruiting TABLE lightning.metastore.rrcc.trialmatch.trial AS overall_status = 'RECRUITING';

LIST DQ USL lightning.metastore.rrcc.trialmatch;
